import os
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from functools import wraps
import xml.etree.ElementTree as ET
import requests

app = Flask(__name__)
DATABASE = '/var/lib/app/metadata.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def verify_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-API-Key', '')
        key_hash = hashlib.sha256(key.encode()).hexdigest()
        db = get_db()
        row = db.execute('SELECT 1 FROM api_keys WHERE key_hash = ?', (key_hash,)).fetchone()
        if not row:
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

def parse_config_payload(xml_data):
    """Parse XML configuration payload from trusted internal services.
    Uses standard library parser for lightweight config documents.
    """
    try:
        root = ET.fromstring(xml_data)
        config = {}
        for item in root.findall('.//setting'):
            name = item.get('name')
            value = item.text
            if name and value:
                config[name] = value
        return config, None
    except ET.ParseError as e:
        return None, str(e)

@app.route('/api/v2/config/import', methods=['POST'])
@verify_api_key
def import_config():
    """Import configuration from XML payload.
    Accepts application/xml content type.
    """
    content_type = request.content_type or ''
    if 'xml' not in content_type.lower():
        return jsonify({'error': 'content-type must be application/xml'}), 415

    xml_data = request.get_data(as_text=True)
    if len(xml_data) > 65536:
        return jsonify({'error': 'payload too large'}), 413

    config, error = parse_config_payload(xml_data)
    if error:
        return jsonify({'error': f'parse error: {error}'}), 400

    db = get_db()
    for key, value in config.items():
        db.execute(
            'INSERT OR REPLACE INTO app_config (key, value, updated_at) VALUES (?, ?, datetime("now"))',
            (key, value)
        )
    db.commit()
    return jsonify({'imported': len(config)}), 200

@app.route('/api/v2/config/export', methods=['GET'])
@verify_api_key
def export_config():
    db = get_db()
    rows = db.execute('SELECT key, value FROM app_config').fetchall()
    result = {row['key']: row['value'] for row in rows}
    return jsonify(result), 200

@app.route('/internal/webhook', methods=['POST'])
def internal_webhook():
    """Receives notifications from internal services.
    No auth required — expected to be network-isolated.
    """
    payload = request.get_json(force=True)
    callback_url = payload.get('callback_url', '')
    event_type = payload.get('event_type', '')

    if not callback_url or not event_type:
        return jsonify({'error': 'missing fields'}), 400

    # Acknowledge the event by POSTing back to the callback
    try:
        resp = requests.post(callback_url, json={'ack': True, 'event': event_type}, timeout=5)
        return jsonify({'status': 'acknowledged', 'callback_status': resp.status_code}), 200
    except requests.RequestException as e:
        return jsonify({'status': 'callback_failed', 'detail': str(e)}), 502

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
